from copy import deepcopy
from importlib import import_module
from threading import Timer

from ta_logcollector.logger import get_net_logger
from ta_logcollector.runner import compress_and_move_archive, Runner
from ta_logcollector.settings import (
    LOGGER_PORT,
    rpl_compress,
    rpl_get_logs_location,
    rpl_get_state,
    rpl_hello,
    rpl_quit,
    rpl_start,
    rpl_start_additional,
    rpl_stop,
    rpl_stop_additional,
    rpl_disable_enb_security,
    SERVER_HOST,
)
from ta_logcollector.utils.enums import RunnerStates, StatusCode
from ta_logcollector.utils.internal import rpartial, disable_enb_security
from ta_logcollector.ver import __version__


class ActionRunner(object):
    POSSIBLE_ACTIONS = [
        "hello",
        "start",
        "start_additional",
        "stop",
        "stop_additional",
        "compress",
        "get_state",
        "get_logs_location",
        "disable_enb_security",
        "quit",
    ]

    def __init__(self, log_host, log_port):
        # type: (str, int) -> None
        """
        Simple initialization.
        :param log_host: IP address of logger host
        :param log_port: port of logger host
        """
        self._logger = get_net_logger(log_host, log_port, name="ActionRunner_{}".format(SERVER_HOST))
        self._log_host, self._log_port = log_host, log_port
        self._state_machine = RunnerStateMachine(self._logger)
        self._runner = Runner(log_host, log_port)
        self._logs_location = ""

    @property
    def state(self):
        # type: () -> RunnerStates
        """
        Returns current state

        :return: state
        """
        return self._state_machine.state

    def perform_action_based_on_message(self, data):
        # type: (dict) -> Dict[str, Any]
        """
        Perform action as described in message.

        :param data:
        :return: result of action
        """
        self._ensure_data_is_provided_with_action(data)
        action = data["action"]
        if action in ActionRunner.POSSIBLE_ACTIONS:
            try:
                result = getattr(self, "_action_{}".format(action))(data).copy()
                result.update({"status": StatusCode.OK, "state": self._state_machine.state})
            except StateMachineForbiddenStateTransitionError as err:
                self._logger.debug(err, exc_info=True)
                result = globals()["rpl_{}".format(action)].copy()
                result.update({"status": StatusCode.ForbiddenStateTransition, "state": self._state_machine.state})
        else:
            self._logger.error("Unknown action {0}".format(action))
            result = {"reply": action, "status": StatusCode.OK, "state": self._state_machine.state}
        return result

    @staticmethod
    def _ensure_data_is_provided_with_action(data):
        assert "action" in data, "Provided data does not have 'action': {}".format(data)

    @staticmethod
    def _action_hello(*args):
        rpl_hello_copy = deepcopy(rpl_hello)
        rpl_hello_copy["version"] = __version__
        return rpl_hello_copy

    def _action_start(self, data):
        self._state_machine.state = RunnerStates.STARTING
        self._action_start_template(data)
        self._state_machine.state = RunnerStates.STARTED
        timeout = data["timeout"]
        if timeout:
            self._timeout_timer = Timer(timeout, self._stop_all_on_timeout)
            self._timeout_timer.start()
        return rpl_start

    def _action_start_additional(self, data):
        assert self._state_machine.state == RunnerStates.STARTED, "Action runner is in wrong state = {}".format(
            self._state_machine.state
        )
        self._action_start_template(data)
        return rpl_start_additional

    def _action_start_template(self, data):
        plugins_list = self._prepare_plugins(plugins=data["plugins"], log_host=self._log_host, log_port=self._log_port)
        self._runner.start(plugins_list, data["log_dir"])

    def _action_compress(self, data):
        self._state_machine.state = RunnerStates.COMPRESSING
        compression_type, path = data["compression_type"], data["logs_dir_to_compress"]
        archive_location = compress_and_move_archive(compression_type, path)
        rpl_compress_copy = deepcopy(rpl_compress)
        rpl_compress_copy["logs_location"] = archive_location
        self._logs_location = archive_location
        self._state_machine.state = RunnerStates.READY
        return rpl_compress_copy

    def _action_stop_template(self, data):
        stop_plugins_list = data["stop_plugins"]
        self._runner.stop(stop_plugins_list)

    def _action_stop(self, data):
        if hasattr(self, "_timeout_timer"):
            self._timeout_timer.cancel()
        self._state_machine.state = RunnerStates.STOPPING
        self._action_stop_template(data)
        self._state_machine.state = RunnerStates.STOPPED
        return rpl_stop

    def _action_stop_additional(self, data):
        self._action_stop_template(data)
        return rpl_stop_additional

    def _action_get_state(self, *args):
        rpl_get_state_copy = deepcopy(rpl_get_state)
        rpl_get_state_copy["state"] = self._state_machine.state
        return rpl_get_state_copy

    def _action_get_logs_location(self, *args):
        rpl_get_logs_location_copy = deepcopy(rpl_get_logs_location)
        rpl_get_logs_location_copy["logs_location"] = self._logs_location
        return rpl_get_logs_location_copy

    def _action_disable_enb_security(self, *args):
        self._state_machine.state = RunnerStates.PROCESSING
        disable_enb_security(self._logger)
        rpl_disable_enb_security_copy = deepcopy(rpl_disable_enb_security)
        self._state_machine.state = RunnerStates.READY
        return rpl_disable_enb_security_copy

    @staticmethod
    def _action_quit(*args):
        return rpl_quit

    def _stop_all_on_timeout(self):
        self._action_stop({"stop_plugins": None})

    def _prepare_plugins(self, plugins, log_host, log_port=LOGGER_PORT):
        # type: (dict, str, int) -> list
        """
        Prepare list of plugins instances based on dict description.

        :param plugins: description of plugins instances
        :param log_host: host name or ip address
        :param log_port: port number
        :return: list on plugin instances
        """
        instances = []
        for name in plugins:
            try:
                module = import_module("ta_logcollector.plugins.{}".format(name))
                plugin_func = getattr(module, name)
                args, kwargs = self._extract_plugins_params(plugins[name])
                instances.append(rpartial(plugin_func, log_host, log_port, *args, **kwargs))
            except Exception as err:
                self._logger.exception(err)
        return instances

    @staticmethod
    def _extract_plugins_params(plugin):
        # type: (dict) -> Tuple[tuple, dict]
        """
        Add missing default values of plugin parameters and return as args and kwargs.

        :param plugin: plugin description
        :return: tuple od plugins' args and kwargs
        """
        if not plugin:
            _args = ()
            _kwargs = {}
        else:
            _args = plugin.get("args", ())
            _kwargs = plugin.get("kwargs", {})
        return _args, _kwargs


class RunnerStateMachine(object):
    """Simple state machine with define transition between states."""

    TRANSITIONS = {
        RunnerStates.READY: [RunnerStates.STARTING, RunnerStates.PROCESSING],
        RunnerStates.PROCESSING: [RunnerStates.READY],
        RunnerStates.STARTING: [RunnerStates.STARTED],
        RunnerStates.STARTED: [RunnerStates.STOPPING],
        RunnerStates.STOPPING: [RunnerStates.STOPPED],
        RunnerStates.COMPRESSING: [RunnerStates.READY],
        RunnerStates.STOPPED: [RunnerStates.COMPRESSING, RunnerStates.STARTING],
    }

    def __init__(self, logger):
        # type: (Logger) -> None
        """
        Simple initialization.
        :param logger: network logger
        """
        self._state = RunnerStates.READY
        self.logger = logger
        self.logger.debug(msg="{!r}".format(self.state))

    def _get_next_possible_state(self):
        # type: () -> list
        return RunnerStateMachine.TRANSITIONS[self.state]

    @property
    def state(self):
        # type: () -> RunnerStates
        """
        Get current state.

        :return: current state
        """
        return self._state

    @state.setter
    def state(self, new_state):
        # type: (RunnerStates) -> None
        """
        Transit to new _state.

        :param new_state: new _state
        """
        if new_state in self._get_next_possible_state():
            old_state, self._state = self._state, new_state
            self.logger.debug("State changed from {} to {}".format(old_state.name, new_state.name))
        else:
            raise StateMachineForbiddenStateTransitionError(
                "Forbidden transition from {} to {}".format(self._state.name, new_state.name)
            )


class StateMachineForbiddenStateTransitionError(Exception):
    pass
